import { cn } from "@/lib/utils";

interface HandwrittenNoteProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  arrowPosition?: "left" | "right" | "top" | "bottom";
  arrowClassName?: string;
  side?: "left" | "right" | "none";
  arrowOffsetX?: number;
  arrowOffsetY?: number;
}

export function HandwrittenNote({
  children,
  arrowPosition = "left",
  arrowClassName,
  className,
  side = "none",
  arrowOffsetX = 0,
  arrowOffsetY = 0,
  ...props
}: HandwrittenNoteProps) {
  return (
    <div
      className={cn(
        // No responsive gate here: where the note is shown differs between
        // the phone and desktop compositions, so each caller decides.
        "font-caveat flex rotate-[-4deg] items-center gap-3 text-2xl text-neutral-500 opacity-80 dark:text-neutral-400 select-none",
        side === "left" && "absolute top-0 right-[calc(100%+3rem)] w-max",
        side === "right" && "absolute top-0 left-[calc(100%+3rem)] w-max",
        arrowPosition === "top" || arrowPosition === "bottom"
          ? "flex-col"
          : "flex-row",
        className,
      )}
      {...props}
    >
      {arrowPosition === "right" || arrowPosition === "bottom" ? (
        <>
          <span>{children}</span>
          <div
            style={{
              transform: `translate(${arrowOffsetX}px, ${arrowOffsetY}px)`,
            }}
          >
            <Arrow className={cn("h-16 w-16 shrink-0", arrowClassName)} />
          </div>
        </>
      ) : (
        <>
          <div
            style={{
              transform: `translate(${arrowOffsetX}px, ${arrowOffsetY}px)`,
            }}
          >
            <Arrow className={cn("h-16 w-16 shrink-0", arrowClassName)} />
          </div>
          <span>{children}</span>
        </>
      )}
    </div>
  );
}

